-- Stored, UNIQUE product codes (the "Code: FAS379" badges).
--
-- The storefront used to derive these from title/category/id on every read.
-- They are real data now: this adds the column, backfills every existing
-- product with the exact code its badge already shows, and enforces
-- uniqueness with an index. New products get their code from
-- allocateProductCode, which adds -2, -3 … when the derived one is taken.
--
-- 55 base codes are shared by more than one product. The oldest row keeps
-- the plain code; the others get a numeric suffix. Nothing else changes on
-- screen for the 1,443 products whose code was already unique.
--
-- Idempotent: the column and index use IF NOT EXISTS and the backfill only
-- fills blank codes, so an edited code is never overwritten by a re-run.

alter table public.products add column if not exists code text;

update public.products as p
set code = v.code
