-- lower() keeps FAS379 and fas379 from both being stored. Applied after the
-- backfill so the suffix allocation above can settle every existing clash.
create unique index if not exists products_code_unique_idx
  on public.products (lower(code));

comment on column public.products.code is
  'Unique human-readable item code shown on cards and in the admin, e.g. FAS379 or FAS379-2.';
